'use strict';

const fs = require('fs');
const path = require('path');

const WORKSPACE = __dirname;
const MANIFEST_NAME = 'backup-manifest.json';
const MANIFEST_PATH = path.join(WORKSPACE, MANIFEST_NAME);

function collectFiles(workspace) {
  return fs
    .readdirSync(workspace, { withFileTypes: true })
    .filter((entry) => !entry.name.startsWith('.'))
    .filter((entry) => entry.name !== MANIFEST_NAME)
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name)
    .sort();
}

function main() {
  const files = collectFiles(WORKSPACE);
  const manifest = { files };
  fs.writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2) + '\n');
  console.log(`Wrote ${MANIFEST_NAME} with ${files.length} file(s):`);
  for (const name of files) {
    console.log(`  - ${name}`);
  }
}

main();

