'use strict';

(async () => {
  const fs = (await import('node:fs')).default;
  const path = (await import('node:path')).default;

  const MANIFEST_NAME = 'backup-manifest.json';
  const scriptPath = process.argv[1] ? path.resolve(process.argv[1]) : process.cwd();
  const workspace = path.dirname(fs.realpathSync(scriptPath));
  const manifestPath = path.join(workspace, MANIFEST_NAME);

  const files = fs
    .readdirSync(workspace, { withFileTypes: true })
    .filter((entry) => !entry.name.startsWith('.'))
    .filter((entry) => entry.name !== MANIFEST_NAME)
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name)
    .sort();

  fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');

  console.log(`Wrote ${MANIFEST_NAME} with ${files.length} file(s):`);
  for (const name of files) {
    console.log(`  - ${name}`);
  }
})();

